name: mockingjay_dyn_bypass
doc: >
  Mockingjay with dynamic bypass confidence. A new 2-bit saturating counter table
  (bypass_conf) tracks the confidence of bypass decisions per PC signature. It is
  decremented when a sampled line is reused quickly (age <= 73) and incremented
  when reused late (age > 73) or evicted without reuse. Bypassing only occurs if
  confidence is >= 2, reducing wrong_bypass mistakes.

state:
  - name: etr
    scope: per_line
    kind: signed
    width: 5
    init: 0
  - name: etr_clock
    scope: per_set
    kind: counter
    width: 4
    init: 8
  - name: set_clock
    scope: per_set
    kind: counter
    width: 8
    init: ZERO

victim:
  key: etr
  extremum: max_magnitude
  tie_break: prefer_negative
  on_search: none
  bypass_when:
    - table: {table: rdp, index: pc_sig, cmp: gt, threshold: 73}
      words: {check_conf: {table: bypass_conf, index: pc_sig, limit: 2}}
    - table_exceeds_victim: {table: rdp, index: pc_sig, div: 8}
      words: {check_conf: {table: bypass_conf, index: pc_sig, limit: 2}}

signatures:
  - name: pc_sig
    source: ip
    fold: [hit, prefetch]
    hash: crc3
    low_bits: 11

